class Solution {
public:
    int maximumLength(vector<int>& nums) {
        int c_even = 0, c_odd = 0;
        for (int x : nums) {
            if (x % 2 == 0) c_even++;
            else c_odd++;
        }
        int alt1 = 0, exp1 = 0;
        int alt2 = 0, exp2 = 1;
        for (int x : nums) {
            int p = (x % 2 + 2) % 2;
            if (p == exp1) {
                alt1++;
                exp1 ^= 1;
            }
            if (p == exp2) {
                alt2++;
                exp2 ^= 1;
            }
        }
        return max({c_even, c_odd, alt1, alt2});
    }
};

class Solution {
    public int maximumLength(int[] nums) {
        int cEven = 0, cOdd = 0;
        for (int x : nums) {
            if (x % 2 == 0) cEven++;
            else cOdd++;
        }
        int alt1 = 0, exp1 = 0;
        int alt2 = 0, exp2 = 1;
        for (int x : nums) {
            int p = (x % 2 + 2) % 2;
            if (p == exp1) {
                alt1++;
                exp1 ^= 1;
            }
            if (p == exp2) {
                alt2++;
                exp2 ^= 1;
            }
        }
        return Math.max(Math.max(cEven, cOdd), Math.max(alt1, alt2));
    }
}

